<?php
require_once __DIR__ . '/includes/bootstrap.php'; adminRequireLogin(); $conn=adminDb();
$column=mysqli_query($conn,"SHOW COLUMNS FROM customers LIKE 'is_active'"); if(!$column||mysqli_num_rows($column)===0) @mysqli_query($conn,'ALTER TABLE customers ADD COLUMN is_active TINYINT(1) NOT NULL DEFAULT 1');
if($_SERVER['REQUEST_METHOD']==='POST'){if(!adminVerifyPost())adminRedirect('customer-details.php','Request expired.');if(isset($_POST['toggle_status'])){$stmt=mysqli_prepare($conn,'UPDATE customers SET is_active=IF(is_active=1,0,1) WHERE email=?');mysqli_stmt_bind_param($stmt,'s',$_POST['email']);mysqli_stmt_execute($stmt);adminRedirect('customer-details.php','Customer status updated.');}if(isset($_POST['delete']))adminRedirect('customer-details.php',deleteCustomer($_POST['email'])?'Customer deleted.':'Could not delete customer.');}
$customers=adminRows('SELECT user,email,address,phone,is_active FROM customers ORDER BY user');$counts=array('all'=>count($customers),'active'=>0,'inactive'=>0);foreach($customers as $customer)$counts[$customer['is_active']?'active':'inactive']++;
$adminTitle='Customers';$adminPage='customers';$adminStyles=array('workflow-tabs.css');include __DIR__.'/includes/header.php';
?>
<section class="admin-card"><div class="admin-toolbar"><div><h2>Customer accounts</h2><p class="admin-muted">Pause an account to stop new orders without removing its history.</p></div></div><nav class="admin-workflow-tabs" id="customer-status-tabs"><button type="button" data-status="all" class="is-active">All <span><?php echo $counts['all']; ?></span></button><button type="button" data-status="active">Active <span><?php echo $counts['active']; ?></span></button><button type="button" data-status="inactive">Inactive <span><?php echo $counts['inactive']; ?></span></button></nav><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Address</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($customers as $row){?><tr data-status="<?php echo $row['is_active']?'active':'inactive';?>"><td><?php echo adminEscape($row['user']);?></td><td><?php echo adminEscape($row['email']);?></td><td><?php echo adminEscape($row['phone']);?></td><td><?php echo adminEscape($row['address']);?></td><td><form method="post"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken());?>"><input type="hidden" name="email" value="<?php echo adminEscape($row['email']);?>"><button class="admin-status-toggle <?php echo $row['is_active']?'is-active':'';?>" name="toggle_status"><i class="bi <?php echo $row['is_active']?'bi-toggle-on':'bi-toggle-off';?>" aria-hidden="true"></i><?php echo $row['is_active']?'Active':'Inactive';?></button></form></td><td><form method="post" onsubmit="return confirm('Delete this customer?')"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken());?>"><input type="hidden" name="email" value="<?php echo adminEscape($row['email']);?>"><button class="admin-icon-button danger" name="delete"><i class="bi bi-trash" aria-hidden="true"></i></button></form></td></tr><?php }?></tbody></table></div></section>
<script>document.querySelectorAll('#customer-status-tabs button').forEach(function(button){button.addEventListener('click',function(){var table=document.querySelector('.admin-table');document.querySelectorAll('#customer-status-tabs button').forEach(function(tab){tab.classList.toggle('is-active',tab===button)});document.querySelectorAll('.admin-table tbody tr').forEach(function(row){row.dataset.paginationMatch=button.dataset.status==='all'||row.dataset.status===button.dataset.status?'true':'false';});if(table)table.dispatchEvent(new Event('foodera-pagination-filter'));});});</script>
